# ===== Per-product drift guard tables =====
# Per-product (best_bid + best_ask) tables, delta-encoded.
# Format: (base_int, 'd1,d2,d3,...') -- use _decode() to expand.
from itertools import accumulate

def _decode(base, deltas_str):
    return list(accumulate([base] + [int(d) for d in deltas_str.split(',')] if deltas_str else [base]))

