def get_target(prod, ts):
    """Latest target at or before ts via binary search on changes list."""
    events = SMOOTH_TARGETS.get(prod)
    if not events:
        return 0
    if ts < events[0][0]:
        return 0
    if ts >= events[-1][0]:
        return events[-1][1]
    lo, hi = 0, len(events) - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if events[mid][0] <= ts:
            lo = mid
        else:
            hi = mid - 1
    return events[lo][1]




